// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testRegression_property() public {
        address rewardToken = address(0x1234);
        c.addReward(rewardToken);
        address newDistributor = address(0xDEAD);
        c.setRewardDistributor(newDistributor);
        assertTrue(c.rewardDistributor() == newDistributor, "rewardDistributor should be updated");
    }
}
